import{_ as p,a0 as n,w as o,s as r,ao as h,I as l,x as e,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT x X-CMD","titleTemplate":false,"description":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Oh My Zsh 和 Powerlevel10k：天作之合 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221227.1 ⭐️⭐️ oh my zsh and powerlevel10k A Match Made in Heaven","title":"Oh My Zsh 和 Powerlevel10k：天作之合","tag":"202301","desc":""},"relativePath":"202301/20221227.1 ⭐️⭐️ oh my zsh and powerlevel10k A Match Made in Heaven.md","filePath":"[post].md"}'),d={name:"202301/20221227.1 ⭐️⭐️ oh my zsh and powerlevel10k A Match Made in Heaven.md"};function g(k,s,u,b,c,w){const i=n("Link");return o(),r("div",null,[s[25]||(s[25]=h('<h1 id="oh-my-zsh-和-powerlevel10k-天作之合" tabindex="-1">Oh My Zsh 和 Powerlevel10k：天作之合 <a class="header-anchor" href="#oh-my-zsh-和-powerlevel10k-天作之合" aria-label="Permalink to “Oh My Zsh 和 Powerlevel10k：天作之合”">​</a></h1><blockquote><p>這是一篇快速而簡單的指南，用 Oh My Zsh 和 Powerlevel10k 主題改造你的 Zsh 終端 Shell，使其在 Ubuntu 和其他 Linux 發行版中看起來很酷。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/ohp10k.jpg" alt=""></p><p>大多數 Linux 發行版中的默認 Shell 是 Bash。Bash 是一個可靠的和傳統的工具。然而，它缺乏一些自定義功能，比如漂亮的顏色、光標支持等等。</p><p>你可以使用另一個 Shell，即 Zsh 來得到更多的設置調整，並幫助你擴展你的 Bash Shell 體驗。</p><p>這個簡單的指南解釋瞭如何安裝 Zsh、Oh My Zsh 並應用 Powerlevel10k 主題。</p><h3 id="oh-my-zsh-和-powerlevel10k-安裝和配置指南" tabindex="-1">Oh My Zsh 和 Powerlevel10k 安裝和配置指南 <a class="header-anchor" href="#oh-my-zsh-和-powerlevel10k-安裝和配置指南" aria-label="Permalink to “Oh My Zsh 和 Powerlevel10k 安裝和配置指南”">​</a></h3><h4 id="_1、安裝-zsh-和改變-shell" tabindex="-1">1、安裝 Zsh 和改變 Shell <a class="header-anchor" href="#_1、安裝-zsh-和改變-shell" aria-label="Permalink to “1、安裝 Zsh 和改變 Shell”">​</a></h4><p>打開一個終端，使用以下適用於你的發行版的命令安裝 Zsh。</p><p>Ubuntu、Debian、Linux Mint 和所有相關的發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install zsh</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install zsh</span></span></code></pre></div><p>Arch：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S zsh</span></span></code></pre></div><p>安裝完成後，找出 Zsh 的安裝路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>whereis zsh</span></span></code></pre></div><p>然後使用當前用户的 Zsh 可執行路徑改變 Shell。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chsh -s /usr/bin/zsh &lt;用户名 &gt;</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/change-the-shell-for-the-current-user.jpg" alt="改變當前用户的 Shell"></p><p>關閉並再次打開終端。然後你應該看到 Zsh 的首次設置。選擇選項 2。它將用一個默認的主題改變你的 Shell 提示符的外觀，如下圖所示：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/first-time-setup-for-zsh.jpg" alt="Zsh 的首次設置"></p><h4 id="_2、安裝-oh-my-zsh" tabindex="-1">2、安裝 Oh My Zsh <a class="header-anchor" href="#_2、安裝-oh-my-zsh" aria-label="Permalink to “2、安裝 Oh My Zsh”">​</a></h4><p>Oh My Zsh 是一套可以進一步定製 Zsh 的腳本。</p>',24)),l("p",null,[s[1]||(s[1]=e("首先，我們將從 GitHub 上下載 Oh My Zsh 腳本來安裝它。如果你有 ",-1)),s[2]||(s[2]=l("code",null,"wget",-1)),s[3]||(s[3]=e(" 和 ",-1)),s[4]||(s[4]=l("code",null,"git",-1)),s[5]||(s[5]=e(" 軟件包，那就最好了。如果還沒有安裝，請使用以下命令 ",-1)),t(i,{href:"https://www.debugpoint.com/wget-not-found-error/"},{default:a(()=>[...s[0]||(s[0]=[e("安裝 wget",-1)])]),_:1}),s[6]||(s[6]=e(" & git：",-1))]),s[26]||(s[26]=h(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install wget</span></span>
<span class="line"><span>sudo apt install git</span></span></code></pre></div><p>然後用下面的命令安裝 Oh My Zsh：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh -c &quot;$(wget -O- https://raw.githubusercontent.com/ohmyzsh/ohmyzsh/master/tools/install.sh)&quot;</span></span></code></pre></div><p>然後你應該看到 Oh My Zsh 及默認主題 Robbyrussell 應用到了你的終端。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Install-oh-my-zsh-and-default-theme.jpg" alt="安裝 Oh My Zsh 和默認主題"></p>`,5)),l("p",null,[s[8]||(s[8]=e("Oh My Zsh 還附帶了其他的主題，你可以 ",-1)),t(i,{href:"https://www.debugpoint.com/install-use-zsh/"},{default:a(()=>[...s[7]||(s[7]=[e("使用這篇指南",-1)])]),_:1}),s[9]||(s[9]=e(" 安裝它們。然而，在本教程中，我將談論一個特定的主題，即 Powerlevel10k。",-1))]),s[27]||(s[27]=h('<h4 id="_3、為-oh-my-zsh-安裝-powerlevel10k-主題" tabindex="-1">3、為 Oh My Zsh 安裝 Powerlevel10k 主題 <a class="header-anchor" href="#_3、為-oh-my-zsh-安裝-powerlevel10k-主題" aria-label="Permalink to “3、為 Oh My Zsh 安裝 Powerlevel10k 主題”">​</a></h4><p>打開終端，運行以下命令，從 GitHub 上克隆 Powerlevel10k 代碼庫，並將文件放到 Oh My Zsh 的配置文件夾中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/romkatv/powerlevel10k.git $ZSH_CUSTOM/themes/powerlevel10k</span></span></code></pre></div><p>用文本編輯器打開 <code>~/.zshrc</code> 文件，將 <code>ZSH_THEME</code> 變量設為 <code>&quot;powerlevel10k/powerlevel10k&quot;</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ~</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano .zshrc</span></span></code></pre></div><p>默認情況下，它應該是 Robbyrussell。刪除 <code>”robbyrussell&quot;</code>，添加下面的 <code>&quot;powerlevel10k/powerlevel10k&quot;</code>。</p><p>更改後，你的 <code>~/.zshrc</code> 文件應該是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZSH_THEME=&quot;powerlevel10k/powerlevel10k”</span></span></code></pre></div><p>保存並關閉該文件（<code>CTRL+O</code>、回車和 <code>CTRL+X</code>）。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/change-oh-my-zsh-theme-to-powerlevel10k.jpg" alt="改變 Oh My Zsh 主題為 Powerlevel10k"></p><p>重新啓動你的終端，啓動首次嚮導來設置 Powerlevel10k 主題。</p><h4 id="_4、powerleve10k-的首次設置" tabindex="-1">4、Powerleve10k 的首次設置 <a class="header-anchor" href="#_4、powerleve10k-的首次設置" aria-label="Permalink to “4、Powerleve10k 的首次設置”">​</a></h4><p>安裝後啓動終端時，Powerlevel10k 會提示你各種問題以瞭解你的 Linux 發行版設置。所以，根據你的需要按下鍵，按照你的口味來定製你的終端。下面是一些問題的例子截圖，可以給你一些啓發。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/powerlevel10k-wizard1.jpg" alt="Powerlevel10k - wizard1"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/powerlevel10k-wizard-2.jpg" alt="Powerlevel10k - wizard2"></p><p>最後，你可以保存文件，享受你的終端的新面貌。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/After-applying-settings-in-powerlevel10k-zsh-theme.jpg" alt="應用 Powerlevel10k Zsh 主題設置後"></p><p>如果你想再次重啓配置嚮導，運行以下程序。你可以隨心所欲地做，次數不限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>p10k configure</span></span></code></pre></div><p>基本設置就這樣結束了。如果你想了解更多，請繼續閲讀。</p><h3 id="更多配置-高級用法" tabindex="-1">更多配置（高級用法） <a class="header-anchor" href="#更多配置-高級用法" aria-label="Permalink to “更多配置（高級用法）”">​</a></h3><h4 id="_5、安裝-dracula-gnome-終端主題" tabindex="-1">5、安裝 Dracula GNOME 終端主題 <a class="header-anchor" href="#_5、安裝-dracula-gnome-終端主題" aria-label="Permalink to “5、安裝 Dracula GNOME 終端主題”">​</a></h4><p>如果你使用的是帶有原生終端應用的 GNOME 桌面，你可以試試令人驚歎的 Drakula 主題。要做到這一點，打開一個終端，運行下面的命令來下載該主題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/dracula/gnome-terminalcd gnome-terminal</span></span></code></pre></div><p>打開 GNOME “終端”應用，進入偏好設置。通過點擊 “+” 添加一個新的配置文件，並命名為 “drakula”。然後進入顏色標籤，取消勾選 “<ruby>使用系統主題的顏色<rt>use colors from system theme</rt></ruby>” 選項。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/create-a-new-profile-for-terminal.jpg" alt="為終端創建一個新的配置文件"></p><p>回到終端，運行以下程序。當出現提示時，選擇你剛才創建的配置文件名稱，如上所述。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./install.sh</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/applying-the-drakula-theme-for-gnome-terminal.jpg" alt="為 GNOME “終端”應用 Drakula 主題"></p><p>一旦安裝完成，回到偏好設置中，將 Drakula 配置文件標記為默認。</p><h4 id="_6、zsh-的自動補完和語法高亮" tabindex="-1">6、Zsh 的自動補完和語法高亮 <a class="header-anchor" href="#_6、zsh-的自動補完和語法高亮" aria-label="Permalink to “6、Zsh 的自動補完和語法高亮”">​</a></h4><p>你可能想試試由社區開發的兩個可用於 Zsh 的插件。它們是 zsh-autosuggestions 和 zsh-syntax-highlighting。</p><p>打開終端，運行以下程序，下載 zsh-autosuggestions，並將其放在插件文件夾中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/zsh-users/zsh-autosuggestions.git $ZSH_CUSTOM/plugins/zsh-autosuggestions</span></span></code></pre></div><p>同樣地，為語法高亮插件運行以下程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/zsh-users/zsh-syntax-highlighting.git $ZSH_CUSTOM/plugins/zsh-syntax-highlighting</span></span></code></pre></div><p>通過文本編輯器打開 <code>~/.zshrc</code>文件（使用以下命令），並找到 <code>plugins=(git)</code> 一行。並將其替換為以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano ~/.zshrc</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins=(git zsh-autosuggestions zsh-syntax-highlighting)</span></span></code></pre></div><p>使用 <code>CTRL+O</code>、回車和 <code>CTRL+X</code> 保存並關閉該文件。</p><p>關閉並打開你的終端。現在，你應該可以使用自動建議和語法高亮了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這樣就好了！你現在應該已經在你的系統上安裝了 Oh My Zsh 和 Powerlevel10k 主題。你可以根據自己的需要，進一步定製 Powerlevel10k 主題的外觀和行為。</p><p>乾杯。</p><hr>',46)),l("p",null,[s[11]||(s[11]=e("via: ",-1)),t(i,{href:"https://www.debugpoint.com/oh-my-zsh-powerlevel10k/"},{default:a(()=>[...s[10]||(s[10]=[e("https://www.debugpoint.com/oh-my-zsh-powerlevel10k/",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=e("作者：",-1)),t(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:a(()=>[...s[12]||(s[12]=[e("Arindam",-1)])]),_:1}),s[17]||(s[17]=e(" 選題：",-1)),t(i,{href:"https://github.com/lkxed"},{default:a(()=>[...s[13]||(s[13]=[e("lkxed",-1)])]),_:1}),s[18]||(s[18]=e(" 譯者：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...s[14]||(s[14]=[e("wxy",-1)])]),_:1}),s[19]||(s[19]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...s[15]||(s[15]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[20]||(s[20]=[e("LCTT",-1)])]),_:1}),s[23]||(s[23]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:a(()=>[...s[21]||(s[21]=[e("Linux中國",-1)])]),_:1}),s[24]||(s[24]=e(" 榮譽推出",-1))])])}const v=p(d,[["render",g]]);export{f as __pageData,v as default};
